const A = (args && args.label) ? args : {"label": "lf", "sizeKB": 1600, "steps": [{"id": "B27Sa", "title": "Exterior style pass A: the autumn look"}, {"id": "B27Sb", "title": "Exterior style pass B: the dressing"}, {"id": "B27Ta", "title": "Interior style pass A: the rooms"}, {"id": "B27Tb", "title": "Interior style pass B: catalog re-themes and the guy's wardrobe"}, {"id": "LF1", "title": "Immersive interiors"}, {"id": "LF2", "title": "Mocha's size and the orca"}, {"id": "LF3", "title": "Menus that never freeze"}, {"id": "LF4", "title": "High and Ultra graphics tiers"}, {"id": "LF5", "title": "Elegant pop-ups"}], "tracks": [{"name": "S", "ids": ["B27Sa", "B27Sb", "LF3", "LF4"]}, {"name": "T", "ids": ["B27Ta", "LF1", "B27Tb"]}], "after": ["LF5"], "extra": {"B27Sa": "READ FIRST: /tmp/harness/lookfeel/plan.md section 3 (the LOOK-AND-FEEL PREAMBLE; it overrides the brief), then sections 2 (tracks), 4 (who may edit what) and 5 (runtime contracts). Seams S0 and L0 are already applied in your copy; treat their lines as read-only unless the plan names your step as the owner. Match the approved mockups (/home/user/Booknest/ghost-town/previews/scene-mock/shots and shots-int, kit-core.js/kit-ext.js/kit-int.js and their port notes) and the owner's references in /tmp/harness/refs/ closely; say per view what still differs.  This step is large: time budget about 150 minutes; ship CORE fully.", "B27Sb": "READ FIRST: /tmp/harness/lookfeel/plan.md section 3 (the LOOK-AND-FEEL PREAMBLE; it overrides the brief), then sections 2 (tracks), 4 (who may edit what) and 5 (runtime contracts). Seams S0 and L0 are already applied in your copy; treat their lines as read-only unless the plan names your step as the owner. Match the approved mockups (/home/user/Booknest/ghost-town/previews/scene-mock/shots and shots-int, kit-core.js/kit-ext.js/kit-int.js and their port notes) and the owner's references in /tmp/harness/refs/ closely; say per view what still differs.  This step is large: time budget about 150 minutes; ship CORE fully.", "B27Ta": "READ FIRST: /tmp/harness/lookfeel/plan.md section 3 (the LOOK-AND-FEEL PREAMBLE; it overrides the brief), then sections 2 (tracks), 4 (who may edit what) and 5 (runtime contracts). Seams S0 and L0 are already applied in your copy; treat their lines as read-only unless the plan names your step as the owner. Match the approved mockups (/home/user/Booknest/ghost-town/previews/scene-mock/shots and shots-int, kit-core.js/kit-ext.js/kit-int.js and their port notes) and the owner's references in /tmp/harness/refs/ closely; say per view what still differs.  This step is large: time budget about 150 minutes; ship CORE fully.", "B27Tb": "READ FIRST: /tmp/harness/lookfeel/plan.md section 3 (the LOOK-AND-FEEL PREAMBLE; it overrides the brief), then sections 2 (tracks), 4 (who may edit what) and 5 (runtime contracts). Seams S0 and L0 are already applied in your copy; treat their lines as read-only unless the plan names your step as the owner. Match the approved mockups (/home/user/Booknest/ghost-town/previews/scene-mock/shots and shots-int, kit-core.js/kit-ext.js/kit-int.js and their port notes) and the owner's references in /tmp/harness/refs/ closely; say per view what still differs.  This step is large: time budget about 150 minutes; ship CORE fully.", "LF1": "READ FIRST: /tmp/harness/lookfeel/plan.md sections 2, 4 and 5 (they override the brief), and your design section. Seams S0 and L0 are already applied; their lines are read-only unless the plan names your step as the owner. Time budget about 90 minutes. The owner's words: 'when you go inside a building, you can really be inside the building and be immersed into it... the whole world disappears... as if you're in the building for real.'", "LF2": "READ FIRST: /tmp/harness/lookfeel/plan.md sections 2, 4 and 5 (they override the brief), and your design section. Seams S0 and L0 are already applied; their lines are read-only unless the plan names your step as the owner. Time budget about 90 minutes. The owner's words: 'Mocha looks really large compared to the other characters' and 'the dolphin's a really good idea, it just looks a bit poorly done.'", "LF3": "READ FIRST: /tmp/harness/lookfeel/plan.md sections 2, 4 and 5 (they override the brief), and your design section. Seams S0 and L0 are already applied; their lines are read-only unless the plan names your step as the owner. Time budget about 90 minutes. The owner's words: 'some of the menus kind of freeze up' and 'when I was at the cafe, it froze'.", "LF4": "READ FIRST: /tmp/harness/lookfeel/plan.md sections 2, 4 and 5 (they override the brief), and your design section. Seams S0 and L0 are already applied; their lines are read-only unless the plan names your step as the owner. Time budget about 90 minutes. The owner's words: 'if there's a better way to make the graphics look better, like if it needs to be more on a computer, that's okay.' Decisions: /tmp/harness/lookfeel/signoff.json (bloomUltra true).", "LF5": "Runs on the MERGED file. READ /tmp/harness/lookfeel/plan.md section 7 item 2 first. Reproduce the cafe freeze on a 4x-throttled 393x852 phone before and after. Time budget about 90 minutes."}, "notes": "This is the LOOK-AND-FEEL UPDATE the owner asked for before batch 4 (Nov 3). Base = /tmp/harness/base-lf.html = the published hotfix snapshot (commit 095613e: controls v3: left floating stick + right-thumb look, no buttons, never stuck; guy-only wardrobe) + seams S0 and L0. NOTE: /home/user/Booknest/ghost-town/index.html holds the hotfix WITHOUT the seams; the merge writes the merged result over it. Batch 4 is PAUSED in /tmp/harness/trackA, trackB and paused-b4: never touch them. The owner's feedback this morning: the stick froze and forced movement (fixed by the hotfix); he hated the rotate buttons (gone); he wants his walker always a guy; Mocha is too large; interiors should be Animal-Crossing immersive; menus froze, especially at the cafe; the orca/'dolphin' looks poorly done; graphics should look better, fine if a computer is needed; 'it doesn't really look like the pictures that I referenced'; pop-ups (names, bubbles) are scattered and don't make sense (LF5). THE BAR is his own 9 pictures in /tmp/harness/refs/ (s1-s5 exterior, i1-i4 interior; c1-c3 his guy) and the approved in-engine mockups in /home/user/Booknest/ghost-town/previews/scene-mock/. Plan: /tmp/harness/lookfeel/plan.md (sections 6 merge glue and 6.3 cross-track checks are REQUIRED for the merge engineer). Decisions: /tmp/harness/lookfeel/signoff.json. NEVER revert the three.js loader or the split #err texts; never bring back the cozy rotate buttons or girl-coded options for his walker. RESUMED after a container restart: seams and LF2 (track T) were already done; B27Sa and B27Ta restart from their step backups.", "outOfScope": "batch 4 (B28-B34: inner life, wants, workshop, visits, nest, Wendell II, records; paused) and batch 5 (B35-B42: gathering, shifts, economy, council, condo, October layer, B41 sky/holiday lights/winter market, B42 critique loop)", "qaShots": "inside the cafe (immersive) at 15:00, Lantern Square at 15:30 on PHONE and on ULTRA, Mocha's study at 21:00, the orca mid-breach, a name card on arrival, and the walker in his default look", "lenses": [{"key": "pictures", "prompt": "LENS 1 of /tmp/harness/lookfeel/plan.md section 8 (read it): DOES IT LOOK LIKE HIS PICTURES? Shoot every fixed view on the LIVE build (git show 095613e:ghost-town/index.html > {OUT}/live.html with three.min.js beside it), on the merged build at PHONE and on desktop at ULTRA, at DAY=11-03 15:30 and 21:00 (plus 10-20 and 12-10), and lay them out as before | after PHONE | after ULTRA | reference sheets in {OUT}/pictures/. Judge palette, shape language, light, density, phone legibility; one verdict per view naming the single biggest remaining gap; flag anything copied from a reference. The owner said it 'doesn't really look like the pictures': gaps here rank HIGH."}, {"key": "inside", "prompt": "LENS 2 of /tmp/harness/lookfeel/plan.md section 8 (read it): INSIDE A BUILDING (LF1 with B27Ta/Tb rooms). Walk into and out of every enterable building in portrait, landscape, Duo and desktop at 10:30, 19:00 and 22:00 and in rain: fades, nothing outside drawn (inside().leaks empty, void pixel test), framing like the approved interior mockups and i1-i4, who is drawn, watch mode following Mocha in and out, the cabin and decorate, taps, reload inside, budgets (draws <=80/100, swaps <12 ms, 0 compiles). The bar: 'the whole world disappears... as if you're in the building for real.' Screenshots to {OUT}/inside/."}, {"key": "phone", "prompt": "LENS 3 of /tmp/harness/lookfeel/plan.md section 8 (read it): PHONE PLAYTEST, FEEL, MENUS AND CONTROLS (LF3, controls v3, LF5). iPhone 393x852 touch dpr 2 at 1x and 4x CPU: follow Mocha; walk to the cafe with the left stick while looking with the right thumb; go in; talk to Juniper, item card, see everything, buy, sit; diary/feed/Mocha tabs, the map, Your Look (six changes), the shop sheet; decorate the cabin; walk to a pier end at sunset. Record Event Timing, long tasks, renders behind sheets, program links, the test-stick freeze scenarios, hit maps, and screenshots of every sheet in 4 viewports; compare with /tmp/harness/lookfeel/menus/menus-1x.json and menus-4x.json. Check LF5: one bubble at a time, name cards, the context button, notices, quiet while busy. The bar: every tap answers within about a frame at 1x, nothing freezes >100 ms at 1x, the stick never sticks, nothing pops over the stick or look areas."}, {"key": "computer", "prompt": "LENS 4 of /tmp/harness/lookfeel/plan.md section 8 (read it): THE COMPUTER TIER (LF4). Desktop 1100x820 and a 2560x1440 window: PHONE vs HIGH vs ULTRA side by side at 15:30 and 21:00 (exteriors and two rooms) next to s1-s4, i2, i3 into {OUT}/computer/. PHONE parity exactly (draws, programs, render targets, pixels). The tier machinery (auto guess, saved decision, Settings row, live switch hitch, ADAPT demotion, WebGL1 and context-loss fallbacks, memory). Tilt-shift never blurs the walker or Mocha; bloom lights lamps and windows only. The bar: ULTRA is the expensive version of the same pictures."}, {"key": "characters", "prompt": "LENS 5 of /tmp/harness/lookfeel/plan.md section 8 (read it): CHARACTERS AND THE SEA (LF2, B27Tb). Mocha's size against the walker, Wendell, keepers and townsfolk in every camera layer at levels 1 and 16, face legibility at follow distance 18, bubble placement, brightest object outdoors. THE GUY: clearly a guy in every look against c1-c3 and i1, no removed option back, pre-hotfix and hotfix saves migrate, the outfit wall. THE ORCA: frozen at u=.2/.5/.8 from both sides plus the spout and calf, never through a pier or the ferry, viewer-aware frequency in a 30-minute soak, backlit at golden hour, spouts only at night, looks original and reads as a cute believable orca at phone size. Screenshots to {OUT}/chars/."}, {"key": "runtime", "prompt": "LENS 6 of /tmp/harness/lookfeel/plan.md section 8 (read it): RUNTIME SAFETY, MERGE INTEGRITY AND PERFORMANCE. Boot with zero page errors in 3 viewports at DAY=11-03, 10-20, 12-10, 07-15 with a fresh save, a pre-hotfix save (from e7d8990) and a hotfix-era save (095613e); dead-zone placement of every new block; diff the seam and territory anchors against /tmp/harness/base-lf.html and read every character-merged hunk; program count after prewarm and 0 late links through a trip start, 20 door swaps, sea events, tier switches, selfies; constant light count; draws/tris per fixed view vs base-lf plus indoor budgets; GLOWPTS/POOLS caps; localStorage size; a 20-minute soak for memory growth; the bias audit (G.act/G.target/G.mode never written); the full test run."}], "prior": {"T": [{"id": "LF2", "title": "Mocha's size and the orca", "summary": "LF2 (Track T, step 1 of 4) is done in /tmp/harness/trackT/index.html (= /tmp/harness/b27t/index.html). The backup is /tmp/harness/backup-LF2.html. CORE A1, A2 and B1-B5 are all built and pass /tmp/harness/test-LF2.js (32/32). smoke.js 15 at DAY=11-03 prints OK on all 3 viewports. Of STRETCH, only the S2 sound recipes are in.\n\nA1, MOCHA'S SIZE\n- Line ~1193:\n  - `growScale=()=>1.05+.01*Math.min(15,level()-1)`: 1.05 at level 1, 1.20 at level 16.\n  - New helpers on the next two lines: `mFloatY=f=>f+.24+.5*growScale()` (hover, hem .24 above the surface) and `mSeatY=s=>s+.27*growScale()` (sitting, hem sinks .23*gs into the seat).\n- updateMocha:\n  - hover alt is `mFloatY(navFloor(G.x,G.z))`; the bed is `mSeatY(1.88)`.\n  - The whole bob (including the beat and startle terms) is multiplied by `sc/1.55`.\n  - cinema `ty=mSeatY(1.33)`; ferry `ty=mFloatY(3.785)`.\n  - Wheel gondola `ty=mSeatY(tmpV.y-1.05)`. DEVIATION from the design's y-1.82: the gondola box spans y-1.8..y-.2, and y-1.82 put his hem .26 under its floor. Now the hem is .51 above the floor and his eyes peek over the rim.\n- `benchY` returns `mSeatY(s.y0+s.h)`.\n- `needleStep`:\n  - the car returns `mFloatY(cy)` (the car floor is cy, since the 2.3-tall car is centred at cy+1.15; the design's cy+.135 was based on the car mesh line);\n  - the deck is `mFloatY(N.yt+.15)`.\n- `lhStep` returns `mSeatY(p.h+.28)`.\n- `emoTick` sizes Mocha's emote with `Math.max(.95,sc)`.\n- `tkShot`: Mocha's head is `TKW.y+.32*growScale()`.\n- Pets: fliers use `G.y+.58*growScale()`, and `syncPets` scale is 1.0.\n- Follow camera: `camS` init dist 18; `setCamMode` floor `Math.max(camS.dist,11)`; `zoomLim` follow range [4.5,80].\n- frameUI bubble anchor is `mocha.position.y+1.42*growScale()+(umb?.84*growScale():0)`. DEVIATION: 1.42 instead of 1.55, because 1.55 gave 69 px in the walk cam (spec limit 10-60). It now measures walk 39 px and follow 13 px.\n\nA2, HIS FACE (geometry sizes, so the blink and mouth scale code is untouched)\n- Eye sphere .0975 (was .075) and highlight .0325 at (.0325,.052,.0455), so both are x1.3.\n- Eye group at (\u00b1.2,.62,.53): .02 lower, and x widened from .19 to .2 so the eye gap holds at 14 px or more.\n- Cheek .092, smile torus (.069,.0196), O mouth .0575: all x1.15.\n\nB1-B5, THE SEA\n- The old orca is gone (meshes, orcaT, orcaPos, and its frame line).\n- In its place, right above frame(), is a TDZ-safe block:\n  - `const SEA={m,fx,R:{orca,calf},ev,pend,st:{clk,due,last},last[],n{breach,spout,dolphins},ms,dtE,pier{t,last},maxV,p(FX arrays),stat{live,mistHi,rings}}`\n  - `seaRz`, `seaAnimal(L,rmax,pts,pal,finH)`: a LatheGeometry body (14x20) plus 'sp:8,6' patches, a cone dorsal fin and ellipsoid flukes and flippers, all through mergeParts with literal-hex keys. Black #1E2228, white #F4F1EA, saddle #9AA3AE; the calf's patches are #F2E6DA; the eye is #111418 with a #FFF6E6 highlight.\n  - Patches on BOTH sides: eye patch, flank lobe, eye. Plus the chin, belly and (adult only) saddle.\n  - The adult is 5.2 long with rmax .68. DEVIATION: leaner than the design so the side bounding box reads 2.36-2.4 (spec 2.2-3.6). The calf is 2.9 long with rmax .66.\n- `seaBuild()` is called from the new line `try{seaBuild()}catch(e){console.error('LF2 seaBuild',e)}` right after `const PIERS=`.\n- SEA.m:\n  - one Mesh(BufferGeometry pre-sized for 2 adults + calf = 14,964 verts, CHIBI_MAT);\n  - frustumCulled=false, a manual sphere test, castShadow false, added with worldAdd.\n- SEA.fx:\n  - one 64-instance InstancedMesh, MeshBasic (map, transparent, additive, depthWrite false, instanceColor), the same program as POOLS;\n  - its geometry is 4 stacked quads, one per cell of a 128 px atlas (droplet, foam, ring, mist). Each instance's z column is camera-forward*4000, so only its own cell's quad stays inside the frustum. This avoids a custom shader.\n- Both meshes are registered with `PREWARM.add('sea.m'|'sea.fx')`.\n- The block's functions:\n  - `seaFx`, `seaSplash(x,z,big,side)`, `seaFxTick(dt)`;\n  - `seaDeform(A,px,py,pz,yaw,pit,rol,k,beta)`: CPU fluke stroke and bend, then YXZ rotation, with polynomial trig;\n  - `seaFerryAt(t)`, `seaMask(x,z,o)`, `seaGolden(h)`, `seaNight(h)`, `seaRoll(h,force)`, `seaGate()`, `seaInView`, `seaAnchor(kind,o)`, `seaStart(kind,o)`, `seaAnimalPose`, `seaPoseAll`, `seaFrame(dt)`, `seaSim(n,o)`.\n- frame() has one line, `seaFrame(dt);`, where the orca line was.\n- Breach: .6 s pre-roll with a foam bulge, then a 2.4 s arc (H 2.4, travel centred on the anchor):\n  - pitch is the arc's tangent x.9;\n  - 50% of natural breaches are side-splashes (roll 70\u00b0); forced and pose events default to upright unless `{side:true}`;\n  - curvature k=.22sin(\u03c0u)+.08sin(2\u03c0u), plus a fluke kick on exit;\n  - exit splash 12 drops + 2 puffs; re-entry crown 28 drops + 6 foam (+4 mist on side-splash) + 2 rings (r 1.5 to 7 over 2.6 s);\n  - the calf follows .45 s behind, 4 back and 2 to the side.\n- Spout pass: 2-3 animals (adult, adult, calf at .65 s and 1.1 s):\n  - the back rolls up with a bend wave;\n  - at t=.4, 8 mist quads rise about 2.8;\n  - then a 4-puff foam V-wake.\n- Scheduler:\n  - one event every 240-420 s of real time; the first comes 120-300 s after boot;\n  - viewer-aware: an event starts only within 140 of the camera and inside 15-85% of the screen, otherwise it retries every 1.5 s;\n  - odds: day breach 25 / spout 75; golden hour (\u00b1.75 h of SUN.set) breach \u00d72, aimed toward the sun's azimuth; night spouts only at .35; rain, drizzle, fog or snow \u00d7.5;\n  - gate: IN.on, SHEETS.level()>0 (map included), or (TIER.n===0||SET.saver) with dt EMA over 1/18 s.\n- Pier-end trigger: the walker inside a PIERS rect, within 6 of its west end, camera looking west, for 6 s \u2192 `SEA.pend` 4-12 s later, 30-45 out, in view. At most once per 180 s.\n\nS2 SOUNDS\nA new line after the SFXR table adds 'spout', 'splash' and 'splashS'. They are called guarded with `{x,z,type:'ferry'}`, and the existing 'whoosh' plays on a breach exit.\n\nAUTONOMY AND STATE\nNothing writes G.act, G.target or G.mode, and no userBias term was added. The sea adds no state.\n\nMEASUREMENTS\n- Size:\n  - Level 1: gs 1.05; top at the bob peak 1.89 (rest 1.84); hem at least .04; width 1.65.\n  - Walk cam (dist 7, portrait lineup): Mocha 211.6 px against the walker's 232.2 px (ratio .91).\n  - Level 16: gs 1.20; rest top 2.06 against the walker's 2.12. The bob peak reaches about 2.18, so the level-16 check uses the rest top.\n  - Follow cam at 18 (portrait): 92-103 px tall; eye 14.8 px; eye gap 15.5-16.6 px.\n- Seat contact (hem relative to the seat top):\n\n| Seat | Hem |\n|---|---|\n| bench | -.242 |\n| cinema | -.241 |\n| ferry | +.24 |\n| bed | -.241 |\n| wheel floor | +.508 |\n| Needle car | +.24 |\n| Needle deck | +.24 |\n| lighthouse | +.039 |\n\n- Orca shots (frozen u=.5, castView dist 14): yaw +\u03c0/2 aspect 2.40 with 9% warm-white; yaw -\u03c0/2 aspect 2.36 with 27% warm-white; dorsal-fin band present on both.\n- Motion: tail mean |\u0394y| between u=.2 and .8 is .329; pitch +.856 / -.856; bottom at u=.5 is 1.04.\n- Splashes: at re-entry 42 FX are live and 4 rings pass r>3 within 1.5 s. A spout puts 8 mist instances above y 1.5.\n- Cost: seaFrame mean .12-.16 ms, p90 .2 ms on desktop SwiftShader.\n- Draws: +2 during an event (paired toggles, every pair exactly 2); 0 and both invisible when idle; programs 48 \u2192 48.\n- Mask: sim(500) gives maxX -110.2, minPier 9.4-9.8, minFerry 12.8-14.0, minSail 10.1.\n- Schedule: 2 simulated hours at 15:00 give 21-22 starts, minimum gap 241-249 s. At 23:00, kinds are 0 breaches, about 700 spouts and about 1300 none (out of 2000 rolls).\n- Pier trigger fires in under 20 simulated seconds, with its anchor on screen.\n\nFILES\n- Shots in /tmp/harness/b27t/shots/lf2/: lf2-walk-default.png, lf2-walk-level16.png, follow-18.png, orca-side-a.png, orca-side-b.png, orca-u20.png, orca-u80.png, orca-side-splash.png, orca-reentry-splash.png, orca-spout.png, pier-trigger.png.\n- Edit scripts: /tmp/harness/b27t/lf2/apply_a.py, apply_b.py, apply_c.py; block source /tmp/harness/b27t/lf2/sea_block.js (later fixes were applied in place in index.html).\n- Ledgers: entries appended to /tmp/harness/b27t/ledger.json and /tmp/harness/draws.json.", "added_hooks": ["__mocha.mochaSize() -> {gs,top,hem,width,eyePx,eyeGap,px,headPxY,anchorPxY,zoom:zoomLim(),topRest,followDist,y,floor}", "__mocha.sea() -> {on,kind,u,t,frz,next,pend,last:[{kind,x,z,at,seen,trig}],n:{breach,spout,dolphins},verts,draws,ms,mVis,fxVis,fx:{live,mistHi,rings[]},pose:{x,z,hd,pit,rol,k,bottom,tdy},pier,maxV}", "__mocha.sea.force(kind,{x,z,heading,freeze,side,pod})", "__mocha.sea.freeze(u|null)", "__mocha.sea.pose(u) -> {u,pit,rol,k,bottom,tdy,y,tail}", "__mocha.sea.bend(u1,u2) -> {n,meanDy} (tail vertices, local y)", "__mocha.sea.sim(n,{hour,secs}) -> {n,maxX,minPier,minFerry,minSail,maxAbsZ,kinds?,starts?,minGap?,first?}", "__mocha.sea.step(n,dt) -> sea()+{stepMax} (advances seaFrame without rendering; tests only)", "__mocha.sea.end(), __mocha.sea.due(s), __mocha.sea.S (the SEA object)", "__mocha.lf2Seats() -> seat contact table {gs,bench,cinema,ferry,bed,wheel{floorHem},needleCar,needleDeck,lighthouse,bike}"], "tests": "/tmp/harness/test-LF2.js passes 32/32. Run it with: NODE_OPTIONS=\"--require /tmp/harness/redirect.js\" MOCHA_FILE=/tmp/harness/trackT/index.html node /tmp/harness/test-LF2.js. The output is in /tmp/harness/b27t/lf2/test-out.txt.\n\nIt has two sections:\n- Portrait 393x852 at 15:00 on DAY 11-03: the size, follow, bubble, seats, orca-look pixel tests from both sides, motion, splash, spout, mask, schedule, IN and sheet gating, and the pier trigger.\n- Desktop 1100x820: idle visibility, paired-toggle draws (+2), programs (+0) and seaFrame cost.\n\nsmoke.js 15 at DAY=11-03 (through the redirect) prints OK (no errors) on desktop, portrait and landscape.\n\nperf1 (desktop, 12:00, DAY 11-03), backup \u2192 after: average 696 \u2192 632 draws, tris 186k \u2192 172k. The drop comes from the follow distance of 18; the sea adds 0 draws when idle.\n\nNot run (left to the batch review, per the lean testing rule): smoke.js 1, test-B9, B11, B14, B17, B23, B26, test-controls, test-stick, test-guy, and the bias audit.", "known_issues": ["INTEGRATION: IN.on is still the L0 stub. seaGate() reads IN.on and is tested with __mocha.lfForce.in(1,'cafe'). Once LF1 lands, the sea must stay gated indoors, and the SEA meshes are added with worldAdd, so LF1's WORLD hiding covers them.", "INTEGRATION: SHEETS.level()>0 and the TIER.n===0||SET.saver over-budget gate both read the L0 stubs (LF3 and LF4 own them). With the stubs, the map sheet blocks the sea (tested). Re-check with LF3's real sheets.", "INTEGRATION: PREWARM.add('sea.m',()=>SEA.m) and PREWARM.add('sea.fx',()=>SEA.fx) are registered. SEA.m uses CHIBI_MAT and SEA.fx uses POOLS's material parameters, so the program count is +0 here (48 \u2192 48). After the merge, confirm that SEA.fx still matches POOLS's program key if LF4 or B27Sa change POOLS's material, the fog or the map encoding.", "INTEGRATION: frame() has exactly one LF2 line, `seaFrame(dt);`, where the orca line was. Track S owns the rest of frame(). The old `orcaT/orcaPos/orca` names are gone, so any Track S code that referenced them must be dropped.", "INTEGRATION: the sound recipes 'spout', 'splash' and 'splashS' are added by an Object.assign(SFXR,...) line right after the SFXR table. They play positionally with type 'ferry'. Muffling when IN.on (LF1) is not done.", "INTEGRATION: the seaBuild() call sits on the line right after `const PIERS=` (Track T territory, per plan section 4).", "Design deviations (all needed to meet the acceptance numbers): wheel gondola ty=mSeatY(y-1.05), not y-1.82; Needle car mFloatY(cy) and deck mFloatY(N.yt+.15), not cy+.135; bubble anchor 1.42*gs, not 1.55*gs; adult orca rmax .68 with a ~.95 cone fin above the back (overall length/height about 2.4), not the chunkier body; eye x \u00b1.2 instead of \u00b1.19.", "The level-16 check uses his rest top (2.06 against the walker's 2.12). At the bob peak he reaches about 2.18, slightly above the walker. Fixing that would need a smaller hover or bob at high levels, which would push the hem below the floor at the bob's low point.", "The scene mockups (previews/scene-mock KIT.mocha scale 1.05, hover .24+.525) are not re-rendered. That is part of S5 STRETCH and was not done.", "STRETCH not built: S1 (Mocha's orca-spotting / ferry trigger with his emote, bubble, diary memory and news line), S3 (white-sided dolphins; their 15% of the odds currently goes to spouts and SEA.n.dolphins stays 0), S4 (pod of 3 for breaches, spyhop, tail-slap, gulls, golden-hour GLOWPTS glint) and S5 (night pool, level-up grow moment). Townsfolk 'orca' activity trigger (design 3.4 item 3) not built.", "audio().st did not show a 'spout' count in the test (the hook may not expose `st`). audShot('spout') is still called once per spouting animal. This check is not part of CORE.", "Regressions not run in this step (lean testing rule): test-B9, B11, B14, B17, B23 (Mocha's two-shot head is now TKW.y+.32*gs), B26, test-controls, test-stick, test-guy, smoke.js 1 and the bias audit."], "smoke_passed": true, "draws": "Desktop perf1 at 12:00 on DAY 11-03, backup \u2192 after: average 696 \u2192 632 draws (max 713 \u2192 648) and tris 186,260 \u2192 172,416. The drop comes from the closer default follow distance (18 instead of 24).\n\n- Idle: the sea adds 0 draws; SEA.m and SEA.fx are both invisible.\n- During an event: +2 draws, exactly 2 in every one of 6 paired visibility toggles in a frozen view.\n- Programs: 48 \u2192 48 (+0). No new lights.\n- Event geometry: 9.8k vertices for a breach (adult + calf), 15.0k at most (2 adults + calf).\n- seaFrame: mean .12-.16 ms, p90 .2 ms on desktop SwiftShader during a stepped breach."}]}}
const ALL = A.steps || []
const TRACKS = (A.tracks && A.tracks.length) ? A.tracks : [{ name: 'main', ids: ALL.map(s => s.id) }]
const AFTER = A.after || []
const LABEL = A.label || 'b3'
const OUT = '/tmp/harness/rv-' + LABEL
const FILE = '/home/user/Booknest/ghost-town/index.html'
const BASE = '/tmp/harness/base-' + LABEL + '.html'
const EXTRA = A.extra || {}
const NOTES = A.notes || ''
const PARALLEL = TRACKS.length > 1
const titleOf = id => ((ALL.find(s => s.id === id) || {}).title || id)
const trackFile = t => PARALLEL ? '/tmp/harness/track' + t.name + '/index.html' : FILE
const ENV = f => f === FILE ? '' : 'NODE_OPTIONS="--require /tmp/harness/redirect.js" MOCHA_FILE=' + f + ' '

const STEP_RESULT = {
  type: 'object',
  properties: {
    summary: { type: 'string', description: 'precise handoff: what you built, function names, data shapes, where things live, hooks' },
    added_hooks: { type: 'array', items: { type: 'string' } },
    tests: { type: 'string' },
    known_issues: { type: 'array', items: { type: 'string' }, description: "include every cross-track dependency as an item starting with 'INTEGRATION:'" },
    smoke_passed: { type: 'boolean' },
    draws: { type: 'string', description: 'draw-call ledger before -> after, tris' },
  },
  required: ['summary', 'added_hooks', 'tests', 'known_issues', 'smoke_passed', 'draws'],
}

function stepPrompt(id, ctx) {
  const n = ctx.handoffs.length
  const per = n ? Math.max(1200, Math.floor(26000 / n)) : 0
  const prev = n ? ctx.handoffs.map(h => '### ' + h.id + ' ' + h.title + '\n' + h.summary.slice(0, per) + '\nKnown issues: ' + h.known.join(' | ').slice(0, 600)).join('\n\n') : '(none yet; you are the first step here)'
  const f = ctx.file, env = ENV(f)
  const trackNote = ctx.track ? `
PARALLEL TRACK ${ctx.track.name}: you work on a COPY of the game at ${f} (three.min.js sits beside it). At the same time, other track(s) are building ${ctx.others.map(o => o.ids.map(x => x + ' (' + titleOf(x) + ')').join(', ')).join('; ')} in their own copies. Afterwards a 3-way merge (base ${BASE}) combines the tracks. Rules for a clean merge:
- NEVER edit ${FILE}. Edit only ${f}.
- Do not build or change the other track's scope. Where your step needs something the other track builds (the interfaces are in spec section 2, e.g. sfx(), babble(), CHARLOD, the cast, S.you, the catalog), call it guarded (typeof x==='function'&&x(...)) or leave a tiny stub, and list each spot in known_issues as an item starting with 'INTEGRATION:'.
- Add new code as new lines or blocks. Never reformat, re-indent, reorder or reflow existing code. In shared hot spots (fresh(), migrate(), the window.__mocha hooks object, renderSet and Settings, the HUD slot table, frame()), make the smallest possible insertion, on its own new line where you can.
- Prefix every node test command with: ${env}(it points page.goto of the main file path at your copy). Write your own tests against the normal path file:///home/user/Booknest/ghost-town/index.html so they also work after the merge.
- The other track also runs a browser. Keep to ONE browser at a time yourself, and close it when done.
` : ''
  return `You are implementing build step ${id} ("${titleOf(id)}") of round 2 of "Mocha's Ghost Town", a cozy, autonomous virtual-pet life-sim. It is a SINGLE FILE (three.js r128, about ${A.sizeKB || 960}KB), hosted as a sandboxed claude.ai artifact. You edit: ${f}
READ FIRST: in /tmp/harness/round2-spec.md, read sections "## 0." (shared rules) and "## 2." (ownership and interfaces), then your own section "## ${id}." (search for the headings). Where the brief below and the spec differ, the spec wins.
Context: /tmp/harness/round1-handoff.md, /tmp/harness/r1-review-summary.md and /tmp/harness/batch2-handoff.md (batch 2: doors, nav, interiors, homes, art pipeline, living lights, hangouts). Skim only what is relevant to your step. Earlier steps you build on:
${prev}
${trackNote}
YOUR BRIEF, ACCEPTANCE TESTS AND HOOKS: read the entry with id "${id}" in /tmp/harness/round2-spec.json (fields brief, acceptance, hooks), e.g. python3 -c "import json;[print(json.dumps(x,indent=1)) for x in json.load(open('/tmp/harness/round2-spec.json'))['steps'] if x['id']=='${id}']". Those acceptance tests and hooks are required.
${EXTRA[id] ? '\nEXTRA FOR THIS STEP: ' + EXTRA[id] + '\n' : ''}
PROCESS AND RULES:
- Back up first: cp ${f} /tmp/harness/backup-${id}.html
- Edit with exact-string Python replacements that assert their match count, or with the Edit tool. Keep the file's compact style.
- Keep the three.js loader (<script src="three.min.js"> plus the cdnjs fallback) and the two split #err texts exactly as they are.
- TESTING, LEAN (to save time): run smoke ONCE at 15:00: ${env}node /tmp/harness/smoke.js 15 (must print OK for all 3 viewports). Add ${env}node /tmp/harness/smoke.js 1 only if your step touches night, lights or sleep. Write /tmp/harness/test-${id}.js covering your acceptance tests through window.__mocha hooks and run it. For visual changes, screenshot portrait 393x852 plus ONE other viewport (landscape 852x393 if layout-sensitive, else desktop 1100x820) and look at them with Read. The full 4-viewport sweep happens in the batch review. At most 3 screenshot iterations per view. Rendering is SwiftShader (slow): drive the game with hooks and use generous timeouts.
- Draw ledger: node /tmp/harness/perf1.js /tmp/harness/backup-${id}.html ${f} (before vs after; see spec section 0) and append to /tmp/harness/draws.json. If perf1.js doesn't fit, use window.__mocha.gfx().
- Autonomy is non-negotiable (spec section 0): no user input path may write G.act, G.target or G.mode. User influence goes only through userBias (clamped at 1.2).
- TIME BUDGET: aim to finish in about 75 minutes of work. Ship CORE completely. Do STRETCH only if time remains, otherwise list it in known_issues.
- Never leave the file broken. If you cannot get smoke passing, restore your backup and report smoke_passed=false with details.
- Do not git commit or push.
Return the structured handoff. The next implementer and the merge engineer see only your summary, so make it precise.`
}

async function buildStep(id, ctx, label) {
  const p = stepPrompt(id, ctx)
  let r = await agent(p, { label: label + 'build ' + id + ': ' + titleOf(id).slice(0, 36), phase: ctx.phase, schema: STEP_RESULT })
  if (!r || !r.smoke_passed) {
    log(label + id + ' reported smoke failure or died; running a repair agent')
    r = await agent(p + `\n\nREPAIR MODE: a previous implementer of this same step finished with smoke failing or crashed. Its report: ${JSON.stringify(r).slice(0, 4000)}. Diff the current file against /tmp/harness/backup-${id}.html, then either fix the breakage or finish the step properly. Smoke must pass at the end.`, { label: label + 'repair ' + id, phase: ctx.phase, schema: STEP_RESULT })
  }
  return r
}

const results = []
const PRIOR = A.prior || {}
for (const t of Object.keys(PRIOR)) for (const h of PRIOR[t]) results.push({ ...h, track: t })
const short = () => results.map(r => ({ id: r.id, track: r.track, smoke: r.smoke_passed, known: r.known_issues, hooks: r.added_hooks, draws: r.draws, summary: (r.summary || '').slice(0, 2000) }))

// ---------------- parallel tracks ----------------
phase('Build')
async function runTrack(t) {
  const ctx = { file: trackFile(t), handoffs: (PRIOR[t.name] || []).map(h => ({ id: h.id, title: h.title, summary: h.summary || '', known: h.known_issues || [] })), track: PARALLEL ? t : null, others: TRACKS.filter(o => o !== t), phase: 'Build' }
  const res = []
  for (const id of t.ids) {
    const r = await buildStep(id, ctx, PARALLEL ? t.name + ': ' : '')
    res.push({ id, title: titleOf(id), track: t.name, ...(r || { summary: 'FAILED', smoke_passed: false, known_issues: [], added_hooks: [], tests: '', draws: '' }) })
    if (!r || !r.smoke_passed) { log('track ' + t.name + ': ' + id + ' still failing after repair; stopping this track'); return { track: t.name, stopped_at: id, res } }
    ctx.handoffs.push({ id, title: titleOf(id), summary: r.summary, known: r.known_issues || [] })
    log('track ' + t.name + ': ' + id + ' done')
  }
  return { track: t.name, res }
}
const tr = await parallel(TRACKS.map(t => () => runTrack(t)))
tr.filter(Boolean).forEach(x => results.push(...x.res))
const stopped = TRACKS.filter((t, i) => !tr[i] || tr[i].stopped_at)
if (stopped.length) return { stopped: stopped.map((t, i) => ({ track: t.name, at: tr[TRACKS.indexOf(t)] && tr[TRACKS.indexOf(t)].stopped_at })), results: short() }

// ---------------- merge ----------------
let merge = null
if (PARALLEL) {
  phase('Merge')
  const integ = results.flatMap(r => (r.known_issues || []).filter(k => /INTEGRATION/i.test(k)).map(k => r.id + ': ' + k))
  const ho = results.map(r => '### ' + r.id + ' (track ' + r.track + ') ' + r.title + '\n' + (r.summary || '').slice(0, 2600) + '\nHooks: ' + (r.added_hooks || []).join(', ')).join('\n\n')
  const MERGE_RES = { type: 'object', properties: { merged: { type: 'boolean' }, smoke_passed: { type: 'boolean' }, conflicts: { type: 'string' }, integration: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' }, summary: { type: 'string' } }, required: ['merged', 'smoke_passed', 'conflicts', 'integration', 'tests', 'summary'] }
  const mp = `You are the MERGE engineer for "Mocha's Ghost Town", a single-file three.js r128 game at ${FILE} (a sandboxed claude.ai artifact). Parallel tracks built steps on separate copies of the same base:
- base: ${BASE} (identical to the current ${FILE})
${TRACKS.map(t => '- track ' + t.name + ': ' + trackFile(t) + ' built ' + t.ids.join(', ')).join('\n')}
The spec is /tmp/harness/round2-spec.md (sections 0 and 2 define shared rules and interfaces).
Builder handoffs:
${ho}

INTEGRATION notes from the builders:
${integ.length ? integ.join('\n') : '(none listed; still check the interfaces)'}

DO:
1. cp ${FILE} /tmp/harness/backup-${LABEL}-premerge.html
2. python3 /tmp/harness/merge3.py ${BASE} ${trackFile(TRACKS[0])} ${trackFile(TRACKS[1])} /tmp/harness/merged-${LABEL}.html  (line-level merge, then a character-level merge of conflicting long lines; it prints the remaining conflicts with line numbers). With more than 2 tracks, merge pairwise.
3. Resolve every remaining conflict by hand, keeping BOTH sides' intent. Then hunt for semantic merge problems that make no textual conflict: duplicate top-level declarations (both tracks adding the same const/let/function name is a SyntaxError), duplicate keys in the window.__mocha hooks object, two HUD slots claiming the same place, both tracks changing fresh()/migrate() or the same state field, both adding per-frame work in frame(), CSS rule collisions, duplicated element ids. Syntax-check the main inline script (extract it and run node --check or new Function on it) and grep.
4. Wire up every INTEGRATION item: replace the guarded stubs with the real calls now that both sides exist (for example babble in the talk card, coin and door sfx, keepers in world space vs shelf shopping and the counter, cast members referenced across tracks, the walker's new look in shops and the cabin).
5. Copy the merged file to ${FILE}. Run node /tmp/harness/smoke.js 15 and node /tmp/harness/smoke.js 1 (OK for all 3 viewports), then EVERY step test of this batch (${results.map(r => '/tmp/harness/test-' + r.id + '.js').join(', ')}), the batch-2 tests (/tmp/harness/test-B7.js ... test-B17.js) and the round-1 tests (test-step1b.js ... test-step6.js). Run them one at a time (one browser at a time). Fix integration breakage. If a test fails only because the other track intentionally changed behavior, update the test and say so. Take portrait 393x852 screenshots at 15:00 and 21:00 and look at them.
6. Confirm grep 'src="three.min.js"' still matches and the two split #err texts are intact.
Never leave ${FILE} broken: if you cannot get smoke passing, restore the premerge backup and report merged=false. Do not git commit. Time budget: about 90 minutes.`
  merge = await agent(mp, { label: 'merge tracks', phase: 'Merge', schema: MERGE_RES })
  if (!merge || !merge.merged || !merge.smoke_passed) {
    log('merge incomplete; running a second merge engineer')
    merge = await agent(mp + `\n\nREPAIR MODE: a previous merge engineer did not finish. Its report: ${JSON.stringify(merge).slice(0, 4000)}. Continue from the current state of the files (check ${FILE} and /tmp/harness/merged-${LABEL}.html).`, { label: 'merge repair', phase: 'Merge', schema: MERGE_RES })
  }
  if (!merge || !merge.merged || !merge.smoke_passed) return { stopped: 'merge', merge, results: short() }
  log('merge done: ' + (merge.conflicts || '').slice(0, 120))
}

// ---------------- after-merge steps ----------------
if (AFTER.length) {
  phase('Build after merge')
  const ctx = { file: FILE, handoffs: results.map(r => ({ id: r.id, title: r.title, summary: r.summary || '', known: r.known_issues || [] })), track: null, others: [], phase: 'Build after merge' }
  if (merge) ctx.handoffs.push({ id: 'MERGE', title: 'merge of the tracks', summary: merge.summary + '\nIntegration: ' + merge.integration.join(' | '), known: [] })
  for (const id of AFTER) {
    const r = await buildStep(id, ctx, '')
    results.push({ id, title: titleOf(id), track: 'after', ...(r || { summary: 'FAILED', smoke_passed: false, known_issues: [], added_hooks: [], tests: '', draws: '' }) })
    if (!r || !r.smoke_passed) return { stopped_at: id, merge, results: short() }
    ctx.handoffs.push({ id, title: titleOf(id), summary: r.summary, known: r.known_issues || [] })
    log(id + ' done')
  }
}

// ---------------- review ----------------
const handoffText = results.map(r => `## ${r.id} ${r.title}\n${(r.summary || '').slice(0, 2600)}\nHooks: ${(r.added_hooks || []).join(', ')}\nTests: ${r.tests}\nKnown issues:\n- ${(r.known_issues || []).join('\n- ')}`).join('\n\n')
const COMMON = `
You are reviewing "Mocha's Ghost Town", a SINGLE FILE: ${FILE} (three.js r128), a sandboxed claude.ai artifact (no external fetches except the cdnjs three.js fallback; localStorage plus window.claude db, with a 256KB doc). Mocha is a white ghost who lives fully AUTONOMOUSLY: the user never steers him, and user influence enters only through userBias, clamped to 1.2. The owner (Jesse, from Kansas City) also has his own walkable character. It must run on iPhone portrait 393x852, iPhone landscape 852x393, an unfolded "iPhone Duo" 900x1000 and desktop 1100x820, on battery.
This batch built round-2 steps ${results.map(r => r.id).join(', ')}${PARALLEL ? ' (in parallel tracks, then merged; watch for merge seams)' : ''}. The spec is /tmp/harness/round2-spec.md (sections 0 and 2 plus each step). Implementer handoffs:
${handoffText.slice(0, 32000)}
${merge ? '\nMerge report: ' + JSON.stringify(merge).slice(0, 2500) + '\n' : ''}
${NOTES ? '\nNOTES FROM THE ORCHESTRATOR:\n' + NOTES + '\n' : ''}
Test harness: node /tmp/harness/smoke.js <hour>, plus per-step tests /tmp/harness/test-<id>.js. Playwright and Chromium are preinstalled; rendering is SwiftShader, so it is slow: drive the game with window.__mocha hooks and use generous timeouts. Never run two browsers at once yourself; another reviewer may be running one, so retry a timeout once before concluding.
Out of scope (later batches): ${A.outOfScope || '(none listed)'}. DO report bugs and regressions in what exists now, including earlier features (texting, holidays, trains, gallery, zoom, save sync, doors, nav, interiors, lights, hangouts).
Write scratch files only under ${OUT}/. Do NOT edit index.html in the review or verify stages.`
const FINDINGS = {
  type: 'object',
  properties: { findings: { type: 'array', items: { type: 'object', properties: {
    title: { type: 'string' }, severity: { type: 'string', enum: ['high', 'medium', 'low'] }, category: { type: 'string' },
    location: { type: 'string' }, evidence: { type: 'string' }, repro: { type: 'string' }, suggested_fix: { type: 'string' } },
    required: ['title', 'severity', 'category', 'location', 'evidence', 'repro', 'suggested_fix'] } } },
  required: ['findings'],
}
const LENSES = (A.lenses || []).map(l => ({ key: l.key, prompt: l.prompt.split('{OUT}').join(OUT) }))
phase('Review')
const reviews = await parallel(LENSES.map(l => () => agent(`${COMMON}\n\n${l.prompt}\n\nReturn concrete, verified findings only, at most 15, most important first.`, { label: 'review: ' + l.key, phase: 'Review', schema: FINDINGS })))
const all = reviews.map((r, i) => r ? r.findings.map(f => ({ ...f, lens: LENSES[i].key })) : []).flat()
phase('Triage')
const tri = await agent(`${COMMON}\n\nTriage these raw findings (JSON):\n${JSON.stringify(all)}\nMerge duplicates, drop out-of-scope items and nits, and calibrate severity (high = crash, data loss, broken feature, autonomy violation, unusable on phone, or a serious perf regression). Return the unique list, most severe first, and the dropped titles with reasons.`, { label: 'triage', phase: 'Triage', schema: { type: 'object', properties: { findings: FINDINGS.properties.findings, dropped: { type: 'array', items: { type: 'string' } } }, required: ['findings', 'dropped'] } })
const uniq = (tri && tri.findings) || all
phase('Verify')
const VERDICT = { type: 'object', properties: { real: { type: 'boolean' }, confidence: { type: 'string', enum: ['high', 'medium', 'low'] }, reasoning: { type: 'string' }, refined_fix: { type: 'string' } }, required: ['real', 'confidence', 'reasoning', 'refined_fix'] }
const checked = await pipeline(uniq, async (f, _o, i) => {
  if (f.severity !== 'high') return { ...f, keep: true, unverified: true, fix: f.suggested_fix }
  const v = await agent(`${COMMON}\n\nAdversarially VERIFY this high-severity finding. Try hard to refute it by reading the code paths and running a targeted check if cheap. If it is real, refine the fix to be minimal and safe.\n${JSON.stringify(f)}`, { label: 'verify ' + i + ': ' + f.title.slice(0, 40), phase: 'Verify', schema: VERDICT })
  return { ...f, keep: !!(v && v.real), fix: (v && v.real && v.refined_fix) || f.suggested_fix, verdict: v && v.reasoning.slice(0, 500) }
})
const confirmed = checked.filter(Boolean).filter(f => f.keep)
const rejected = checked.filter(Boolean).filter(f => !f.keep).map(f => f.title)
log(`${confirmed.length} findings to fix (${confirmed.filter(f => f.unverified).length} unverified medium/low), ${rejected.length} rejected`)
phase('Fix')
const FIXRES = { type: 'object', properties: { fixed: { type: 'array', items: { type: 'string' } }, not_fixed: { type: 'array', items: { type: 'string' } }, tests_run: { type: 'string' }, smoke_passed: { type: 'boolean' }, summary: { type: 'string' } }, required: ['fixed', 'not_fixed', 'tests_run', 'smoke_passed', 'summary'] }
const testList = results.map(r => '/tmp/harness/test-' + r.id + '.js').join(', ')
const fixPrompt = (items, n) => `${COMMON}\n\nYou are the FIXER and MAY edit ${FILE}. Back it up first to /tmp/harness/backup-${LABEL}-fix${n}.html. Fix these findings, most severe first. Findings marked unverified=true have NOT been independently checked: confirm each is real (read the code, or run a quick check) before fixing, and skip false ones (list them in not_fixed as 'not real: ...'). Keep fixes minimal and safe, keep autonomy intact, add no per-frame allocation. Keep the three.js loader and the split #err texts intact.\n${JSON.stringify(items)}\nAfterwards both smoke tests (15 and 1) must pass, plus every step test (${testList}), the batch-2 tests (test-B7.js ... test-B17.js) and the round-1 tests (test-step1b.js ... test-step6.js). Update a test only when a fix intentionally changed behavior, and say so. Time budget: about 100 minutes; if you run long, fix all highs first.`
let fix = confirmed.length ? await agent(fixPrompt(confirmed, 1), { label: 'fixer', phase: 'Fix', schema: FIXRES }) : { fixed: [], not_fixed: [], tests_run: 'none', smoke_passed: true, summary: 'nothing to fix' }
phase('QA')
const QARES = { type: 'object', properties: { pass: { type: 'boolean' }, problems: { type: 'array', items: { type: 'string' } }, screenshots: { type: 'array', items: { type: 'string' } }, summary: { type: 'string' } }, required: ['pass', 'problems', 'screenshots', 'summary'] }
const qaPrompt = (fx) => `${COMMON}\n\nFinal QA. The fixer reported: ${JSON.stringify(fx).slice(0, 6000)}\nRun both smoke tests and all step tests (${testList}). Take a final screenshot set into ${OUT}/final/ (4 viewports at 15:00 and 21:00, plus ${A.qaShots || 'inside a shop and inside Mocha\'s house at night'}) and look at them. Spot-check the fixes. Report pass=false only for real breakage (errors, broken features, data-loss risk, severe layout problems). Time budget: about 45 minutes.`
let qa = await agent(qaPrompt(fix), { label: 'qa', phase: 'QA', schema: QARES })
if (qa && !qa.pass && qa.problems.length) {
  fix = await agent(fixPrompt(qa.problems.map(p => ({ title: p, unverified: false })), 2), { label: 'fixer 2', phase: 'QA', schema: FIXRES })
  qa = await agent(qaPrompt(fix), { label: 'qa 2', phase: 'QA', schema: QARES })
}
return { results: short(), merge, confirmed: confirmed.map(f => ({ title: f.title, severity: f.severity, lens: f.lens })), rejected, fix, qa }
